ROOT=Path(__file__).resolve().parents[3];SOURCE=ROOT/'output/pdf/agentic_ai_complete_source';OUT=ROOT/'output/pdf/Agentic_AI_Engineering_publication_readiness.pdf'
for name,file in [('Body','SourceSans3-Regular.ttf'),('Bold','SourceSans3-Semibold.ttf'),('Display','SpaceGrotesk-Bold.ttf')]:pdfmetrics.registerFont(TTFont(name,str(SOURCE/'fonts'/file)))
